head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF07405.xml";
scwin.isSetPopup = false;
scwin.vSelectYear = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/**
 * 콤보박스 값 설정
 */
scwin.fn_searchCode = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstinvstg.specyvalu.instassgn.yearlist";
    dts_BAS_YY.DataID = encodeURI(url);
    dts_BAS_YY.reset();
    var strCbd = "";
    for (j = 1; j <= dts_BAS_YY.getTotalRow(); j++) {
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_BAS_YY.getCellData(j, "VALUE") + "^" + dts_BAS_YY.getCellData(j, "TEXT");
    }
    cmb_BAS_YY.CBData = strCbd;
};
scwin.fn_grdSearchCode = function() {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    strCbdReason = "' ':"; //초기값

    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") == "SPECY_VALU_INST_CD") {
            strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'SPECY_VALU_INST_CD', 'Data', strCbdReason);
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectInstAssgnInput&inputMessageId=SPECY_VALU_ASSGN_INOUT";
        url += "&BAS_YY=" + $c.stf.getObjectValue(cmb_BAS_YY); // 연도

        dts_List.DataID = encodeURI(url);
        dts_List.reset();
        $c.cm.ShowWin(grd_Grid);
    } else {
        var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectInstAssgnInput&inputMessageId=SPECY_VALU_ASSGN_INOUT";
        url += "&BAS_YY=" + $c.stf.getObjectValue(cmb_BAS_YY); // 연도

        dts_List2.DataID = encodeURI(url);
        dts_List2.reset();
        $c.cm.ShowWin(grd_List);
    }
};
scwin.fn_save = function() {
    TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_CheckForm = function() {
    for (var i = 1, j = dts_List.getTotalRow(); i <= j; i++) {
        var status = dts_List.getRowStatus(i);
        if (status == 1 || status == 3) {
            if (dts_List.getCellData(i, "SPECY_VALU_INST_CD") == " ") {
                $c.win.alert(i + "번째행  " + "TCB기관명은 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "BAS_YY") == "") {
                $c.win.alert(i + "번째행  " + "연도는 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "SORT_ORD") == "") {
                $c.win.alert(i + "번째행  " + "배정순번은 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "COL_ORD_SEQ") == "") {
                $c.win.alert(i + "번째행  " + "컬럼순번은 필수값입니다.");
                return false;
            }
            var instCd, rowOrd, colOrd, basYy, instNm;
            var instCdIn, rowOrdIn, colOrdIn, instNmIn, basYyIn;
            instCd = dts_List.getCellData(i, "SPECY_VALU_INST_CD");
            rowOrd = dts_List.getCellData(i, "SORT_ORD");
            colOrd = dts_List.getCellData(i, "COL_ORD_SEQ");
            basYy = dts_List.getCellData(i, "BAS_YY");
            instNm = dts_Cod.getCellData($c.cp.getNameValueRow(dts_Cod, "VALUE", instCd), "TEXT");
            for (var k = 1, l = dts_List.getTotalRow(); k <= l; k++) {
                if (i == k) continue;
                instCdIn = dts_List.getCellData(k, "SPECY_VALU_INST_CD");
                rowOrdIn = dts_List.getCellData(k, "SORT_ORD");
                colOrdIn = dts_List.getCellData(k, "COL_ORD_SEQ");
                instNmIn = dts_Cod.getCellData($c.cp.getNameValueRow(dts_Cod, "VALUE", instCdIn), "TEXT");
                basYyIn = dts_List.getCellData(k, "BAS_YY");
                if (instCd == instCdIn && basYy == basYyIn) {
                    if (rowOrd == rowOrdIn) {
                        $c.win.alert("'" + instNmIn + "' 중복된 배정순번이 존재합니다.");
                        return false;
                    }
                    if (colOrd != colOrdIn) {
                        $c.win.alert("'" + instNmIn + "' 컬럼순번이 다른값이 존재합니다.");
                        return false;
                    }
                }
                if (instCd != instCdIn && basYy == basYyIn) {
                    if (colOrd == colOrdIn) {
                        $c.win.alert("TCB기관별(" + instNm + " ," + instNmIn + ")중복된 컬럼순번이 존재합니다.");
                        return false;
                    }
                }
            }
        }
    }
    return true;
};
scwin.fn_trs = function() {
    if (TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveInstAssgn");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};
scwin.fn_setGrid = function() {
    if (dts_List2.getTotalRow() > 0) {
        dts_List3.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SPECY_VALU_ASSGNVIEW_INOUT";
        dts_List3.Reset();
    }
};
scwin.fn_setGrid2 = function() {
    for (var i = 1, j = 12; i <= j; i++) {
        $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Name", "배정회사" + i);
    }
    var maxRow = $c.cp.nameMax(dts_List2, "SORT_ORD", 0, 0);
    var maxCol = $c.cp.nameMax(dts_List2, "COL_ORD_SEQ", 0, 0);
    for (var i = 1, j = maxRow; i <= j; i++) {
        dts_List3.insertRow();
    }
    for (var i = 1, j = 12; i <= j; i++) {
        if (i <= maxCol) {
            $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Show", true);
        } else {
            $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Show", false);
        }
    }
    for (var k = 1, l = maxCol; k <= l; k++) {
        for (var i = 1, j = maxRow; i <= j; i++) {
            var findRow = $c.cp.getNameValueRow(dts_List2, "MAKED_KEY", i + "_" + k);
            if (findRow > 0) {
                dts_List3.setCellData(i, "COM_NM" + k, dts_List2.getCellData(findRow, "ASSGN_COM_NM"));
                var grdHeadName = $c.cm.getColumnProp(grd_List, "COM_NM" + k, "Name");
                $c.cm.setColumnProp(grd_List, "COM_NM" + k, "Name", dts_List2.getCellData(findRow, "SKIL_VALU_INST_CD_NM"));
            }
        }
    }
    for (var i = 1, j = 12; i <= j; i++) {
        var grdHeadName = $c.cm.getColumnProp(grd_List, "COM_NM" + i, "Name");
        if (grdHeadName.indexOf("배정회사") > -1) {
            $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Show", false);
        }
    }
    $c.stf.FillGridHeaderTotalCnt(maxRow, panel_page);
    $c.cm.CloseWin(maxRow, grd_List);
};
scwin.btn_Search1_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_searchCode();
    scwin.fn_grdSearchCode();
    var firstYear = dts_BAS_YY.getCellData(1, "VALUE");
    $c.stf.setObjectValue(cmb_BAS_YY, firstYear);
    scwin.vSelectYear = firstYear;
    scwin.fn_list_sync();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_searchCode();
    if (scwin.vSelectYear == undefined && dts_BAS_YY.getTotalRow() > 0) {
        $c.stf.setObjectValue(cmb_BAS_YY, dts_BAS_YY.getCellData(1, "VALUE"));
    }
    $c.stf.setObjectValue(cmb_BAS_YY, scwin.vSelectYear);
    scwin.fn_list_sync();
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Delete_onclick = function() {
    $c.cp.removeRow(dts_List, dts_List.getRowPosition());
};
scwin.btn_New_onclick = function() {
    dts_List.insertRow();
    var year = $c.stf.getObjectValue(cmb_BAS_YY);
    if (year != "") {
        dts_List.setCellData(dts_List.getRowPosition(), "BAS_YY", year);
    }
};
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    //fn_SetPar = fn_SetInstPtnt2;
    var wth = 1400;
    var hgt = 830;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("", "ULDSTF07400.gfm", "전문평가관리내역", pt.x, pt.y, wth, hgt, "window");
};
scwin.cmb_BAS_YY_OnSelChange = function() {
    scwin.vSelectYear = $c.stf.getObjectValue(cmb_BAS_YY);
    scwin.fn_list_sync();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    scwin.fn_setGrid();
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    scwin.fn_setGrid2();
};
scwin.btn_Excel_onclick = function() {
    if (dts_List3.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_List, "TCB별 배정내역", "", 8, 0);
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.image_2_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_Grid, "TCB별 배정내역 입력", "", 8, 0);
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
